CSS = """:root{color-scheme:light;--bg:#f4f6f8;--surface:#fff;--ink:#172635;--muted:#536579;--line:#d5dfe7;--accent:#145d80;--good:#186548;--warning:#865100;--bad:#9c2e33;--space:1rem}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,-apple-system,'Segoe UI',sans-serif}header{padding:1.1rem 2rem;background:#172b3b;color:white;display:flex;align-items:center;justify-content:space-between;gap:1rem}.brand{display:flex;gap:.75rem;align-items:center;font-weight:650}.brand small{display:block;color:#c4d5df;font-size:.75rem;font-weight:400}.mark{border:1px solid #819caa;padding:.15rem .6rem;font-size:1.4rem}main{max-width:1240px;margin:auto;padding:2rem}h1{font-size:1.9rem;line-height:1.2;margin:.3rem 0 .7rem;letter-spacing:-.035em}h2{font-size:1rem;margin:0 0 .65rem;font-weight:650}p{margin:.5rem 0}.eyebrow{text-transform:uppercase;font-size:.7rem;letter-spacing:.12em;color:var(--accent);font-weight:700}.muted{color:var(--muted);font-size:.85rem}.title,.actions,.section-title{display:flex;gap:.75rem;align-items:center;justify-content:space-between}.actions{justify-content:flex-end;flex-wrap:wrap}.tag{font-size:.73rem;line-height:1.5;border:1px solid currentColor;padding:.2rem .5rem;white-space:nowrap}.access,.panel,.stats article{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:1.2rem}.access{margin:1.4rem 0}.access form{max-width:600px}.input-row{display:flex;gap:.65rem;margin:.3rem 0}label{font-size:.85rem;font-weight:600}input{min-width:0;flex:1;font:inherit;border:1px solid #7c91a3;border-radius:4px;padding:.6rem .75rem;background:white;color:var(--ink)}button{font:inherit;font-size:.85rem;font-weight:600;padding:.6rem .85rem;border:1px solid #8ba1b1;border-radius:4px;background:white;color:var(--ink);cursor:pointer}button.primary{background:var(--accent);border-color:var(--accent);color:white}button:hover:not(:disabled){filter:brightness(.94)}button:disabled{opacity:.5;cursor:default}:focus-visible{outline:3px solid #a66700;outline-offset:3px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem;margin:1rem 0}.stats h2{color:var(--muted);font-size:.8rem}.stats strong{font-size:1.5rem;font-weight:650;letter-spacing:-.025em}.stats p{margin-bottom:0}.columns{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:1rem}.panel{margin-bottom:1rem;min-width:0}.section-title{align-items:flex-start;flex-wrap:wrap}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;font-variant-numeric:tabular-nums;font-size:.84rem}th{font-weight:600;color:var(--muted);font-size:.73rem}th,td{padding:.65rem .45rem;border-bottom:1px solid var(--line);vertical-align:middle}th:first-child,td:first-child{padding-left:0}meter{width:100%;min-width:5rem;height:1rem}dl{margin:.75rem 0}dt{color:var(--muted);font-size:.78rem}dd{margin:0 0 .65rem}.quality{display:grid;grid-template-columns:1fr auto;gap:.65rem}.quality dd{font-variant-numeric:tabular-nums;font-weight:650}.context code{font-size:.73rem;overflow-wrap:anywhere}.notice{padding:.55rem .75rem;background:#eef3f6;border-left:3px solid #8ca7b9;font-size:.85rem}.notice.good{border-color:var(--good);color:var(--good)}.notice.warn{border-color:var(--warning);color:var(--warning);background:#fff6e5}.notice.bad{border-color:var(--bad);color:var(--bad);background:#fff0f0}.empty{color:var(--muted);padding:1rem 0;font-size:.85rem}.receipts{padding:0;list-style:none}.receipts li{padding:.6rem 0;border-bottom:1px solid var(--line);font-size:.85rem}.receipts small{display:block;color:var(--muted)}footer{padding:1rem 0 2rem;font-size:.83rem;color:var(--muted)}footer strong{display:block;color:var(--ink)}.sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}.skip{position:absolute;top:-80px;left:1rem;background:white;padding:.5rem;z-index:2}.skip:focus{top:0}[hidden]{display:none!important}@media(max-width:850px){main{padding:1.25rem}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.columns{grid-template-columns:1fr}header{padding:1rem 1.25rem}.title{align-items:flex-start;flex-direction:column}}@media(max-width:420px){main{padding:.75rem}header{padding:.75rem;flex-wrap:wrap}.input-row{flex-direction:column}.stats{gap:.5rem}.stats article,.panel,.access{padding:.85rem}h1{font-size:1.6rem}.stats strong{font-size:1.2rem}.tag{white-space:normal}}"""
